from solution import cycpattern_check
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(a, b):
    """Obviously-correct model: True iff some rotation of b is substring of a."""
    if b == "":
        # empty string is a substring of every string (including empty)
        return "" in a
    rotations = [b[i:] + b[:i] for i in range(len(b))]
    return any(r in a for r in rotations)


# ---- spec examples ----

@pytest.mark.parametrize(
    "a,b,expected",
    [
        ("abcd", "abd", False),
        ("hello", "ell", True),
        ("whassup", "psus", False),
        ("abab", "baa", True),
        ("efef", "eeff", False),
        ("himenss", "simen", True),
    ],
)
def test_spec_examples(a, b, expected):
    assert cycpattern_check(a, b) is expected


def test_spec_example_abcd_abd():
    assert cycpattern_check("abcd", "abd") is False


def test_spec_example_hello_ell():
    assert cycpattern_check("hello", "ell") is True


def test_spec_example_whassup_psus():
    assert cycpattern_check("whassup", "psus") is False


def test_spec_example_abab_baa():
    assert cycpattern_check("abab", "baa") is True


def test_spec_example_efef_eeff():
    assert cycpattern_check("efef", "eeff") is False


def test_spec_example_himenss_simen():
    assert cycpattern_check("himenss", "simen") is True


# ---- empty / boundary derived from "substring" semantics ----

def test_empty_pattern_in_nonempty_text():
    assert cycpattern_check("abc", "") is True


def test_empty_pattern_in_empty_text():
    assert cycpattern_check("", "") is True


def test_empty_pattern_in_various_texts():
    assert cycpattern_check("hello", "") is True
    assert cycpattern_check("a", "") is True
    assert cycpattern_check("", "") is True


def test_empty_text_nonempty_pattern_is_false():
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("", "abc") is False


def test_equal_strings_are_true():
    assert cycpattern_check("abc", "abc") is True
    assert cycpattern_check("a", "a") is True
    assert cycpattern_check("", "") is True


def test_single_char_membership():
    assert cycpattern_check("hello", "e") is True
    assert cycpattern_check("hello", "z") is False
    assert cycpattern_check("a", "a") is True
    assert cycpattern_check("a", "b") is False


def test_longer_pattern_cannot_match():
    assert cycpattern_check("ab", "abc") is False
    assert cycpattern_check("", "a") is False
    assert cycpattern_check("a", "aa") is False


