@given(
    st.text(alphabet="abc", min_size=0, max_size=8),
    st.text(alphabet="abc", min_size=0, max_size=4),
    st.integers(min_value=0, max_value=4),
)
def test_rotation_invariance(a, b, k):
    if len(b) == 0:
        rot = b
    else:
        k = k % len(b)
        rot = b[k:] + b[:k]
    assert cycpattern_check(a, b) == cycpattern_check(a, rot)


@given(
    st.text(alphabet="abc", min_size=0, max_size=8),
    st.text(alphabet="abc", min_size=0, max_size=4),
)
def test_reference_equivalence(a, b):
    assert cycpattern_check(a, b) == reference(a, b)


@given(st.text(alphabet="ab", min_size=1, max_size=5))
def test_constructed_rotation_match(b):
    n = len(b)
    rots = [b[i:] + b[:i] for i in range(n)]
    for r in rots:
        a = "x" + r + "y"
        assert cycpattern_check(a, b) is True


@given(st.text(alphabet="abc", min_size=0, max_size=6))
def test_repeated_char_pattern(a):
    b = "a" * len(a) if len(a) > 0 else ""
    expected = reference(a, b)
    assert cycpattern_check(a, b) is expected
